import{_ as l,C as r,o as n,c as s,j as t,a as e,E as o,a5 as c}from"./chunks/framework.BYIUCCsM.js";const q=JSON.parse('{"title":"可调容器","description":"","frontmatter":{},"headers":[],"relativePath":"components/resizable.md","filePath":"components/resizable.md","lastUpdated":1787846564000}'),h={name:"components/resizable.md"},b={id:"可调容器",tabindex:"-1"};function p(u,d,g,z,m,f){const i=r("Badge"),a=r("XhDemo");return n(),s("div",null,[t("h1",b,[d[0]||(d[0]=e("可调容器 ",-1)),o(i,{type:"info",text:"resizable"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#可调容器","aria-label":'Permalink to "可调容器 <Badge type="info" text="resizable" />"'},"​",-1))]),d[3]||(d[3]=c('<p>一块能拖着改尺寸的区域，八条边都能推，键盘也能推。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>尺寸该由用户自己定：可调侧栏、可调卡片、编辑器里的预览区。</li><li>尺寸要记下来：<code>onSizeChangeEnd</code> 就是为此留的，一次调整只发一次。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>两块区域按比例分配、一块变大另一块必须变小：那是<a href="./splitter">分栏</a>，它是守恒的。</li><li>只是表格的列宽：<a href="./table">表格</a>自己就有改宽把手。</li><li>浮在页面上、可拖可调的窗口：用<a href="./floating-panel">浮动面板</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>八条边各一个把手，<code>edges</code> 可以只开放其中几条；没开放的边不显示把手。</li><li><code>minWidth</code> / <code>maxWidth</code> / <code>minHeight</code> / <code>maxHeight</code> 夹住范围，<code>aspectRatio</code> 锁宽高比，<code>step</code> 吸附到整数倍。</li><li>键盘按<strong>屏幕方向</strong>推：推东边时右键变宽、推西边时右键变窄，与拖动完全同义。Home / End 直接推到两端。</li><li>两个回调分工明确：<code>onSizeChange</code> 拖动途中连着发，<code>onSizeChangeEnd</code> 收尾才发一次，存尺寸用后者。</li><li><strong>推西边与北边时容器的起点会动</strong>，那段位移写成 root 的 <code>left</code> / <code>top</code>。皮肤已给 <code>position: relative</code>，开箱即对——<code>relative</code> 的 <code>left</code> / <code>top</code> 是视觉位移、元素仍占原位， 因此对边钉得住。把 root 改成 <code>static</code> 会让这两个方向只变尺寸不移位，看起来像是「拖左边、 右边在长」；只用东 / 南 / 东南三向时没有这个前提。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>八条边各一个把手；拖动改尺寸，Tab 到把手用方向键也能推</p>',10)),o(a,{src:"resizable/01-basic"}),d[4]||(d[4]=t("h3",{id:"只开放部分边",tabindex:"-1"},[e("只开放部分边 "),t("a",{class:"header-anchor",href:"#只开放部分边","aria-label":'Permalink to "只开放部分边"'},"​")],-1)),d[5]||(d[5]=t("p",null,"edges 决定哪几条边可调；没开放的边不显示把手",-1)),o(a,{src:"resizable/02-edges"}),d[6]||(d[6]=t("h3",{id:"约束",tabindex:"-1"},[e("约束 "),t("a",{class:"header-anchor",href:"#约束","aria-label":'Permalink to "约束"'},"​")],-1)),d[7]||(d[7]=t("p",null,"上下限夹住范围，aspectRatio 锁宽高比，step 吸附到整数倍",-1)),o(a,{src:"resizable/03-constraints"}),d[8]||(d[8]=t("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[9]||(d[9]=t("p",null,"把手全部退出 Tab 序列，按下也不进调整",-1)),o(a,{src:"resizable/04-disabled"}),d[10]||(d[10]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-resizable&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhResizableHandle</code> <code>XhResizableRoot</code></td></tr><tr><td>组合式函数</td><td><code>useResizable</code></td></tr><tr><td>状态机</td><td><code>resizableMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/resizable.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;resizable&quot;</code>：<strong><code>root</code></strong> · <code>handle</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>size</code></td><td><code>ResizableSize</code></td><td></td><td>受控尺寸。给了就由外面说了算，内部只发意图。</td></tr><tr><td><code>defaultSize</code></td><td><code>ResizableSize</code></td><td></td><td></td></tr><tr><td><code>minWidth</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>minHeight</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>maxWidth</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>maxHeight</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>aspectRatio</code></td><td><code>number</code></td><td></td><td>宽高比（宽 ÷ 高）。给了就锁死；四条边各按自己那一轴算另一轴，四个角以宽为准。</td></tr><tr><td><code>step</code></td><td><code>number</code></td><td></td><td>吸附步进：宽高各自落到最近的整数倍。</td></tr><tr><td><code>keyboardStep</code></td><td><code>number</code></td><td></td><td>方向键一次推多远（px），默认 8。</td></tr><tr><td><code>keyboardLargeStep</code></td><td><code>number</code></td><td></td><td>按住 Shift 时的步长（px），默认 40。</td></tr><tr><td><code>edges</code></td><td><code>ResizeEdge[]</code></td><td></td><td>允许哪几条边可调，默认八向全开。 只给东南两向就是「只能往右下角撑大」，那是文档流里最常见的形态。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ResizableTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onSizeChange</code></td><td><code>(details: ResizableSizeChangeDetails) =&gt; void</code></td><td></td><td>尺寸变化意图。拖动途中连着发。</td></tr><tr><td><code>onSizeChangeEnd</code></td><td><code>(details: ResizableSizeChangeEndDetails) =&gt; void</code></td><td></td><td>一次调整收尾发一次。存尺寸用它，别用 onSizeChange。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>size-change</code></td><td><code>ResizableSizeChangeDetails</code></td><td>尺寸变化（拖动途中会连发）；detail 为 <code>{ size }</code></td></tr><tr><td><code>size-change-end</code></td><td><code>ResizableSizeChangeEndDetails</code></td><td>一次调整收尾发一次；detail 为 <code>{ size, edge }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhResizableHandle</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhResizableRoot</code></td><td><code>default</code></td><td><code>ResizableRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>resizing</code></p><p><strong>事件</strong>：<code>RESIZE.START</code> · <code>RESIZE.MOVE</code> · <code>RESIZE.END</code> · <code>RESIZE.CANCEL</code> · <code>RESIZE.NUDGE</code> · <code>RESIZE.TO_BOUND</code> · <code>SIZE.SET</code></p><p><strong>判据</strong>：<code>canResize</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useResizable</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>size</code></td><td><code>ResizableSize</code></td><td></td></tr><tr><td><code>offset</code></td><td><code>ResizableOffset</code></td><td></td></tr><tr><td><code>resizing</code></td><td><code>boolean</code></td><td>正在调整（拖动中）。键盘推一步不算。</td></tr><tr><td><code>activeEdge</code></td><td><code>ResizeEdge | null</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>edgeEnabled</code></td><td><code>(edge: ResizeEdge) =&gt; boolean</code></td><td>这条边是否开放。</td></tr><tr><td><code>setSize</code></td><td><code>(size: ResizableSize) =&gt; void</code></td><td>整份赋值：先过约束再落地。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHandleProps</code></td><td><code>(props: { edge: ResizeEdge }) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/windowsplitter/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in handle, not disabled</td><td>按屏幕方向推这条边一步（默认 8px）——推东边是变宽、推西边是变窄，与拖动同义。按的是屏幕方向，rtl 下两键不对调——那时改由「行尾侧」这条边落在屏幕左边来体现</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in handle, not disabled</td><td>往反方向推一步，规则同上</td></tr><tr><td><code>Shift+ArrowRight</code> / <code>Shift+ArrowLeft</code> / <code>Shift+ArrowUp</code> / <code>Shift+ArrowDown</code></td><td>focus in handle, not disabled</td><td>按大步长推（默认 40px）</td></tr><tr><td><code>Home</code></td><td>focus in handle, not disabled</td><td>把这条边推到它眼下能到的最小尺寸</td></tr><tr><td><code>End</code></td><td>focus in handle, not disabled</td><td>推到最大尺寸；没给上限时不动</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>translations?.root</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>handle</code></td><td><code>aria-disabled</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>handle</code></td><td><code>aria-label</code></td><td>translations?.handle?.(edge)</td></tr><tr><td><code>handle</code></td><td><code>aria-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>handle</code></td><td><code>aria-valuenow</code></td><td>Math.round(edge === &#39;n&#39; || edge === &#39;s&#39; ? size.height…</td></tr><tr><td><code>handle</code></td><td><code>role</code></td><td>&#39;separator&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/resizable.css</code> 按部件选择：<code>[data-scope=&quot;resizable&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-edge</code></td><td>context.get(&#39;activeEdge&#39;)</td></tr><tr><td><code>root</code></td><td><code>data-resizing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>handle</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>handle</code></td><td><code>data-edge</code></td><td>edge</td></tr><tr><td><code>handle</code></td><td><code>data-resizing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-resizable-corner</code> · <code>--xh-resizable-grip</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><p><code>edge</code> 说的是<strong>逻辑方向</strong>：<code>e</code> 是行尾侧，从右往左排版时它落在屏幕左边。机器把逻辑边翻成 物理边再算几何——翻的是边不是位移的正负，只翻位移会算对宽度却动错那一头。键盘那侧因此 不看文字方向：方向键按的恒是屏幕方向，与拖动完全同义。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>里面放<a href="./scroll-area">滚动区域</a>，内容超出时自己滚。</li></ul>',40))])}const S=l(h,[["render",p]]);export{q as __pageData,S as default};
